def parse(tree):
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


def greaterSumTree(tree):
    if not tree:
        return []
    val, left, right = parse(tree)
    new = list(val)
    total = 0
    stack = []
    u = 0
    while stack or u != -1:
        while u != -1:
            stack.append(u)
            u = right[u]
        u = stack.pop()
        total += val[u]
        new[u] = total
        u = left[u]
    # nodes are numbered in array order, so write the new values back in that order
    out, k = [], 0
    for x in tree:
        if x == -1:
            out.append(-1)
        else:
            out.append(new[k])
            k += 1
    return out
